"""Shared presentation helpers; no financial or stock mutations."""
from html import escape
from datetime import datetime

def quantity(value=1, minimum=1, maximum=20, label='จำนวน'):
    label=escape(label,quote=True)
    return f'<div class="quantity" role="group" aria-label="{label}"><button type="button" data-step="-1" aria-label="ลด {label}">−</button><input type="number" name="qty" value="{value}" min="{minimum}" max="{maximum}" aria-label="{label}" required><button type="button" data-step="1" aria-label="เพิ่ม {label}">+</button></div>'

def date(value):
    try:
        d=datetime.fromisoformat(value)
        months=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.']
        return f'{d.day} {months[d.month-1]} {d.year+543} · {d:%H:%M}'
    except (ValueError,TypeError): return escape(str(value))

def status(value):
    return {'open':'เปิดบิลอยู่','paid':'ชำระแล้ว','void':'ยกเลิกบิลแล้ว'}.get(value,escape(value))

def progress(current):
    labels=['ตรวจยอด','แบ่งชำระ (ถ้าต้องการ)','รับเงิน','เสร็จสิ้น']
    return '<ol class="checkout-progress" aria-label="ขั้นตอนชำระเงิน">'+''.join(f'<li class="{"done" if i<current else "active" if i==current else ""}" {"aria-current=step" if i==current else ""}><span>{"✓" if i<current else i+1}</span>{text}</li>' for i,text in enumerate(labels))+'</ol>'

CSS='''
button,a,input,select{touch-action:manipulation}button:focus-visible,a:focus-visible{outline:3px solid #f3cb87;outline-offset:4px}button:disabled{opacity:.55;cursor:wait}.quantity{display:inline-flex;align-items:center;border:1px solid var(--border);border-radius:12px;overflow:hidden;flex-shrink:0}.quantity button{background:transparent;color:var(--gold);padding:8px;width:40px;min-height:44px;border:0;border-radius:0}.quantity input{width:44px!important;min-width:0;text-align:center;border:0;padding:8px 0;background:transparent;appearance:textfield}.quantity input::-webkit-inner-spin-button{appearance:none}.menu-bottom{flex-wrap:wrap}.menu-bottom form.fields{flex-wrap:wrap;align-items:center}.menu-bottom form.fields>button{flex:1;min-height:44px}.filters{position:sticky;top:8px;z-index:12;background:#14201df5;padding:12px;border:1px solid var(--border);border-radius:16px;backdrop-filter:blur(12px);scrollbar-width:thin}.menu-art{position:relative}.detail-open{position:absolute;inset:0;width:100%;height:100%;border:0;border-radius:0;background:transparent!important;cursor:zoom-in}.detail-hint{position:absolute;bottom:12px;right:12px;background:#0c181ddd;color:#fff;padding:6px 10px;border-radius:20px;font-size:12px;pointer-events:none}.bottom-bar{background:#1b3028f5;backdrop-filter:blur(16px)}.bottom-bar small{display:block;font-size:11px}.bottom-bar strong{color:var(--gold)}.menu-dialog{color:var(--text,#f5eee0);background:#14221d;border:1px solid #6a6848;border-radius:22px;width:min(94vw,560px);max-height:90dvh;padding:24px;overflow:auto}.menu-dialog::backdrop{background:#000b;backdrop-filter:blur(5px)}.dialog-close{float:right;margin-bottom:10px}.dialog-picture{clear:both;aspect-ratio:16/10;overflow:hidden;border-radius:14px;background:#22362b}.dialog-picture img{width:100%;height:100%;object-fit:cover}.dialog-picture svg{width:100%;height:100%}.menu-dialog .fields{display:flex;flex-wrap:wrap;gap:12px}.menu-dialog p{line-height:1.8}.ux-toast{position:fixed;top:20px;left:50%;transform:translateX(-50%);background:#f0cc8b;color:#10251d;padding:14px 22px;border-radius:12px;z-index:100;box-shadow:0 8px 30px #0005;max-width:90vw}.checkout-progress{list-style:none;display:flex;gap:12px;padding:0;margin:24px 0;flex-wrap:wrap}.checkout-progress li{display:flex;align-items:center;gap:8px;color:#a7b8ac;font-size:13px}.checkout-progress span{display:grid;place-items:center;width:30px;height:30px;border:1px solid #526457;border-radius:50%}.checkout-progress .active{color:#f4ce8f}.checkout-progress .active span{background:#e6bf7d;color:#15251d}.checkout-progress .done span{background:#305e44;color:#d4f2de}.tablecard{border-top:4px solid #659d7a!important}.tablecard.busy{border-top-color:#e3b96d!important}.tablecard.settling{border-top-color:#9f9ae5!important}.tablecard .table-amount{font-size:24px;color:var(--gold);margin:12px 0}.tablecard .table-meta{font-size:13px;line-height:1.9;min-height:50px}.table-legend{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0}.table-legend span{border:1px solid var(--border);border-radius:30px;padding:8px 14px}.tablecard a.button{display:block;text-align:center}.tablecard form button{width:100%}@media(max-width:600px){.quantity button{width:36px}.quantity input{width:36px!important}.bottom-bar{padding:12px 14px;gap:10px}.bottom-bar .button{white-space:nowrap;padding:12px}.checkout-progress{gap:8px}.checkout-progress li{font-size:11px}.menu-dialog{padding:18px}.menu-bottom form.fields{width:100%}}@media(prefers-reduced-motion:no-preference){.menu-item{transition:transform .18s ease,box-shadow .18s ease}.menu-item:hover{transform:translateY(-3px);box-shadow:0 12px 25px #0003}}@media print{.checkout-progress,.ux-toast{display:none}}
'''

SCRIPT='''<dialog class="menu-dialog" id="menu-details" aria-labelledby="detail-title"><button type="button" class="secondary dialog-close">ปิด ✕</button><div class="dialog-picture"></div><h2 id="detail-title"></h2><p class="dialog-description"></p><p class="dialog-price price"></p><div class="dialog-order"></div><small>หากแพ้อาหาร กรุณาแจ้งพนักงานก่อนสั่ง</small></dialog><div class="ux-toast" role="status" aria-live="polite" hidden></div><script>
(()=>{const dialog=document.querySelector('#menu-details'),toast=document.querySelector('.ux-toast');let timer;
function message(text){toast.textContent=text;toast.hidden=false;clearTimeout(timer);timer=setTimeout(()=>toast.hidden=true,4500)}
document.addEventListener('click',e=>{const step=e.target.closest('[data-step]');if(step){const input=step.closest('.quantity').querySelector('input');if(+step.dataset.step>0)input.stepUp();else input.stepDown();input.dispatchEvent(new Event('input',{bubbles:true}));return}
const open=e.target.closest('.detail-open');if(open){const card=open.closest('.menu-item');dialog.querySelector('.dialog-picture').innerHTML=card.querySelector('.menu-art').querySelector('img,svg').outerHTML;dialog.querySelector('h2').textContent=card.querySelector('h3').textContent;dialog.querySelector('.dialog-description').textContent=card.querySelector('.menu-description').textContent;dialog.querySelector('.dialog-price').textContent=card.querySelector('.price').textContent;dialog.querySelector('.dialog-order').innerHTML=card.querySelector('.menu-bottom form')?.outerHTML||'<p>สแกน QR ที่โต๊ะเพื่อสั่ง หรือสอบถามพนักงาน</p>';const source=card.querySelector('.menu-bottom form'),copy=dialog.querySelector('.dialog-order form');if(source&&copy){[...source.elements].forEach(el=>{const target=copy.elements.namedItem(el.name);if(target)target.value=el.value});copy.querySelector('select[name^=option_]')?.dispatchEvent(new Event('change',{bubbles:true}))}dialog.showModal()}
if(e.target.closest('.dialog-close'))dialog.close()});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.addEventListener('submit',async e=>{const form=e.target;if(form.getAttribute('action')!='/customer/cart'||form.querySelector('[name=replace]'))return;e.preventDefault();if(form.dataset.busy)return;form.dataset.busy='1';const button=form.querySelector('button:not([type=button])');if(button)button.disabled=true;
try{const response=await fetch('/customer/cart',{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(new FormData(form))});const data=await response.json();if(!response.ok)throw Error(data.message);document.querySelectorAll('[data-cart-count]').forEach(el=>el.textContent=data.count);document.querySelectorAll('[data-cart-total]').forEach(el=>el.textContent=data.total);if(dialog.open)dialog.close();message('เพิ่มลงตะกร้าแล้ว · ตรวจรายการก่อนยืนยันสั่ง')}
catch(error){message(error.message||'เชื่อมต่อไม่ได้ กรุณาเปิดตะกร้าตรวจรายการก่อนลองอีกครั้ง')}finally{delete form.dataset.busy;if(button)button.disabled=false}});
})();</script>'''

